#!/usr/bin/env python3

import csv
import json
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional, Tuple


MANIFEST_PATH = Path("/root/campaign_manifest.json")
CRATE_COST_PATH = Path("/root/crate_cost.csv")
BILLING_PATH = Path("/root/billing.csv")
OVERRIDES_PATH = Path("/root/location_overrides.csv")
SUSPENSIONS_PATH = Path("/root/suspensions.csv")

OUTPUT_JSON_PATH = Path("/root/vaxcrate_analysis.json")
OUTPUT_MD_PATH = Path("/root/vaxcrate_summary.md")


D2 = Decimal("0.01")


def to_decimal(v: Any) -> Decimal:
    if v is None:
        raise ValueError("Expected numeric value, got None")
    if isinstance(v, Decimal):
        return v
    # json numbers come in as int/float; preserve their literal value via str
    if isinstance(v, (int, float)):
        return Decimal(str(v))
    s = str(v).strip()
    if s == "":
        raise ValueError("Expected numeric value, got empty string")
    return Decimal(s)


def money_round(d: Decimal) -> Decimal:
    return d.quantize(D2, rounding=ROUND_HALF_UP)


def money_float(d: Decimal) -> float:
    # Keep as a JSON number while ensuring 2-decimal rounding.
    return float(money_round(d))


def read_csv_dicts(path: Path) -> List[Dict[str, str]]:
    with path.open("r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        return [dict(row) for row in reader]


def parse_alias_labels(value: Any) -> List[str]:
    if value is None:
        return []
    if isinstance(value, list):
        return [str(x).strip() for x in value if str(x).strip() != ""]
    if isinstance(value, str):
        s = value.strip()
        if s == "":
            return []
        # Allow comma-separated alias strings.
        parts = [p.strip() for p in s.split(",")]
        return [p for p in parts if p]
    # Fallback: coerce to string.
    s = str(value).strip()
    return [s] if s else []


def load_manifest_campaigns(manifest_obj: Any) -> List[Dict[str, Any]]:
    """Return a flat list of campaign dicts from a manifest.

    Supported shapes:
    - list[campaign]
    - {"campaigns": list[campaign]}
    - {"regions": [{"campaigns": list[campaign], ...}, ...]}
    """
    if isinstance(manifest_obj, list):
        return [c for c in manifest_obj if isinstance(c, dict)]

    if isinstance(manifest_obj, dict):
        if isinstance(manifest_obj.get("campaigns"), list):
            return [c for c in manifest_obj["campaigns"] if isinstance(c, dict)]

        if isinstance(manifest_obj.get("regions"), list):
            out: List[Dict[str, Any]] = []
            for region in manifest_obj["regions"]:
                if not isinstance(region, dict):
                    continue
                campaigns = region.get("campaigns")
                if isinstance(campaigns, list):
                    out.extend([c for c in campaigns if isinstance(c, dict)])
            return out

    raise ValueError("Unrecognized campaign_manifest.json structure")


def main() -> None:
    # --- Load data ---
    manifest_obj = json.loads(MANIFEST_PATH.read_text(encoding="utf-8"))
    manifest_campaigns = load_manifest_campaigns(manifest_obj)

    crate_rows = read_csv_dicts(CRATE_COST_PATH)
    billing_rows = read_csv_dicts(BILLING_PATH)
    override_rows = read_csv_dicts(OVERRIDES_PATH)
    suspension_rows = read_csv_dicts(SUSPENSIONS_PATH)

    # --- Build lookup tables ---
    crate_cost_by_tier: Dict[str, Decimal] = {}
    for r in crate_rows:
        tier = (r.get("crate_tier") or "").strip()
        cost = to_decimal(r.get("crate_cost_usd"))
        crate_cost_by_tier[tier] = cost

    billing_by_label: Dict[str, List[Dict[str, str]]] = {}
    for r in billing_rows:
        label = (r.get("campaign_label") or "").strip()
        billing_by_label.setdefault(label, []).append(r)

    overrides_by_campaign: Dict[str, List[Dict[str, str]]] = {}
    for r in override_rows:
        cid = (r.get("campaign_id") or "").strip()
        overrides_by_campaign.setdefault(cid, []).append(r)

    hold_campaign_ids = {
        (r.get("campaign_id") or "").strip()
        for r in suspension_rows
        if (r.get("suspension_status") or "").strip() == "hold"
    }

    # --- Filter campaigns ---
    retained = []
    for c in manifest_campaigns:
        if (c.get("analysis_flag") or "").strip() != "review":
            continue
        cid = (c.get("campaign_id") or "").strip()
        if cid in hold_campaign_ids:
            continue
        retained.append(c)

    # --- Per-campaign resolution and calculations ---
    DAYS_6 = 6
    DAYS_12 = 12
    DISPATCHES_6 = 60
    DISPATCHES_12 = 30

    campaign_outputs: List[Dict[str, Any]] = []

    for c in retained:
        campaign_id = (c.get("campaign_id") or "").strip()
        campaign_name = (c.get("campaign_name") or "").strip()

        alias_labels = parse_alias_labels(c.get("alias_labels"))
        match_labels = [campaign_name] + alias_labels
        match_labels = [lbl.strip() for lbl in match_labels if lbl and lbl.strip()]

        # --- Resolve billing ---
        matched_billing: List[Dict[str, str]] = []
        for lbl in match_labels:
            matched_billing.extend(billing_by_label.get(lbl, []))

        active_billing = [r for r in matched_billing if (r.get("status") or "").strip() == "active"]
        if not active_billing:
            raise ValueError(
                f"No active billing row found for campaign_id={campaign_id} (labels={match_labels})"
            )

        # If multiple, keep lexicographically greatest cycle_tag.
        active_billing.sort(key=lambda r: (r.get("cycle_tag") or "").strip())
        chosen_billing = active_billing[-1]
        payment_per_dispatch_per_clinic = to_decimal(chosen_billing.get("payment_per_dispatch_per_clinic_usd"))

        # --- Resolve active clinics ---
        best_override_revision: Optional[int] = None
        best_override_active_clinics: Optional[int] = None

        for r in overrides_by_campaign.get(campaign_id, []):
            state = (r.get("state") or "").strip()
            rev_raw = (r.get("revision") or "").strip()
            clinics_raw = (r.get("active_clinics") or "").strip()

            if state != "approved":
                continue
            if rev_raw == "" or clinics_raw == "":
                continue

            try:
                rev_num = int(rev_raw)
            except ValueError:
                continue

            try:
                clinics_num = int(clinics_raw)
            except ValueError:
                continue

            if best_override_revision is None or rev_num > best_override_revision:
                best_override_revision = rev_num
                best_override_active_clinics = clinics_num

        if best_override_active_clinics is None:
            default_active = c.get("default_active_clinics")
            if default_active is None or str(default_active).strip() == "":
                raise ValueError(f"No valid override and no default_active_clinics for {campaign_id}")
            active_clinics = int(default_active)
        else:
            active_clinics = int(best_override_active_clinics)

        # --- Resolve crate cost ---
        crate_tier = (c.get("crate_tier") or "").strip()
        if crate_tier not in crate_cost_by_tier:
            raise ValueError(f"Unknown crate_tier={crate_tier!r} for campaign_id={campaign_id}")
        crate_cost = crate_cost_by_tier[crate_tier]

        # --- Inputs from manifest ---
        drug_cost_per_1000 = to_decimal(c.get("drug_cost_per_1000_doses_usd"))
        doses_per_day = to_decimal(c.get("doses_per_day"))

        active_clinics_d = Decimal(active_clinics)

        def annual_revenue(dispatches_per_year: int) -> Decimal:
            return payment_per_dispatch_per_clinic * active_clinics_d * Decimal(dispatches_per_year)

        def annual_drug_cost(days_per_dispatch: int, dispatches_per_year: int) -> Decimal:
            return (
                drug_cost_per_1000
                * active_clinics_d
                * doses_per_day
                * Decimal(days_per_dispatch)
                * Decimal(dispatches_per_year)
                / Decimal(1000)
            )

        def annual_crate_cost(dispatches_per_year: int) -> Decimal:
            # Per task instruction: no active_clinics multiplication unless tests/data require it.
            return crate_cost * Decimal(dispatches_per_year)

        rev6 = annual_revenue(DISPATCHES_6)
        rev12 = annual_revenue(DISPATCHES_12)

        drug6 = annual_drug_cost(DAYS_6, DISPATCHES_6)
        drug12 = annual_drug_cost(DAYS_12, DISPATCHES_12)

        crate6 = annual_crate_cost(DISPATCHES_6)
        crate12 = annual_crate_cost(DISPATCHES_12)

        margin6 = rev6 - drug6 - crate6
        margin12 = rev12 - drug12 - crate12
        diff = margin12 - margin6

        out = {
            "campaign_id": campaign_id,
            "campaign_name": campaign_name,
            "active_clinics": active_clinics,
            "drug_cost_per_1000_doses_usd": float(drug_cost_per_1000),
            "doses_per_day": float(doses_per_day),
            "crate_tier": crate_tier,
            "crate_cost_usd": float(crate_cost),
            "payment_per_dispatch_per_clinic_usd": float(payment_per_dispatch_per_clinic),
            "annual_drug_cost_6_day_usd": money_float(drug6),
            "annual_drug_cost_12_day_usd": money_float(drug12),
            "annual_crate_cost_6_day_usd": money_float(crate6),
            "annual_crate_cost_12_day_usd": money_float(crate12),
            "annual_revenue_6_day_usd": money_float(rev6),
            "annual_revenue_12_day_usd": money_float(rev12),
            "annual_margin_6_day_usd": money_float(margin6),
            "annual_margin_12_day_usd": money_float(margin12),
            "annual_margin_difference_12_minus_6_usd": money_float(diff),
        }
        campaign_outputs.append(out)

    campaign_outputs.sort(key=lambda x: x["campaign_id"])

    total_margin_6 = sum((to_decimal(c["annual_margin_6_day_usd"]) for c in campaign_outputs), Decimal("0"))
    total_margin_12 = sum((to_decimal(c["annual_margin_12_day_usd"]) for c in campaign_outputs), Decimal("0"))

    total_diff = total_margin_12 - total_margin_6
    abs_total_diff = abs(total_diff)

    threshold = Decimal("11000")
    if abs_total_diff < threshold:
        decision = "move_to_12_day"
        justification = (
            f"Absolute margin change ${money_float(abs_total_diff):.2f} is below the $11000 threshold, so move_to_12_day."
        )
    else:
        decision = "keep_6_day"
        justification = (
            f"Absolute margin change ${money_float(abs_total_diff):.2f} exceeds the $11000 threshold, so keep_6_day."
        )

    output = {
        "assumptions": {
            "dispatches_per_year_6_day": DISPATCHES_6,
            "dispatches_per_year_12_day": DISPATCHES_12,
            "days_per_dispatch_6_day": DAYS_6,
            "days_per_dispatch_12_day": DAYS_12,
            "switch_threshold_usd": 11000,
            "override_rule": "highest numeric approved revision with non-empty active_clinics, else default_active_clinics",
            "suspension_rule": "exclude hold campaigns",
        },
        "campaigns": campaign_outputs,
        "totals": {
            "total_annual_margin_6_day_usd": money_float(total_margin_6),
            "total_annual_margin_12_day_usd": money_float(total_margin_12),
            "total_annual_margin_difference_12_minus_6_usd": money_float(total_diff),
            "absolute_total_margin_difference_usd": money_float(abs_total_diff),
        },
        "recommendation": {
            "decision": decision,
            "justification": justification,
        },
    }

    OUTPUT_JSON_PATH.write_text(json.dumps(output, indent=2, sort_keys=False) + "\n", encoding="utf-8")

    md_lines = [
        f"Total annual margin (6-day): ${money_float(total_margin_6):.2f}",
        f"Total annual margin (12-day): ${money_float(total_margin_12):.2f}",
        f"Absolute total margin difference: ${money_float(abs_total_diff):.2f}",
        f"Decision: {decision}",
    ]
    OUTPUT_MD_PATH.write_text("\n".join(md_lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

