            "total_annual_margin_6_day_usd": money_float(total_margin_6),
            "total_annual_margin_12_day_usd": money_float(total_margin_12),
            "total_annual_margin_difference_12_minus_6_usd": money_float(total_diff),
            "absolute_total_margin_difference_usd": money_float(abs_total_diff),
        },
        "recommendation": {
            "decision": decision,
            "justification": justification,
        },
    }

    OUTPUT_JSON_PATH.write_text(json.dumps(output, indent=2, sort_keys=False) + "\n", encoding="utf-8")

    md_lines = [
        f"Total annual margin (6-day): ${money_float(total_margin_6):.2f}",
        f"Total annual margin (12-day): ${money_float(total_margin_12):.2f}",
        f"Absolute total margin difference: ${money_float(abs_total_diff):.2f}",
        f"Decision: {decision}",
    ]
    OUTPUT_MD_PATH.write_text("\n".join(md_lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
